      "path": "lib/shared.js",
      "content": "/**\n * dsh-mysql 纯函数工具集：SQL 语句分类、表白名单校验、JSON 安全转换。\n * 无任何外部依赖，Host（lib/index.js）与单元测试（test/shared.test.mjs）共用。\n */\n\n/** mysql_query 单次返回的最大行数，超出则截断并在结果中标记 truncated。 */\nexport const MAX_ROWS = 2000\n\n/** Read a row property by SQL field label, tolerating server/driver label casing. */\nexport function readRowField(row, fieldName) {\n  if (row === null || typeof row !== 'object' || Array.isArray(row)) return undefined\n  if (Object.prototype.hasOwnProperty.call(row, fieldName)) return row[fieldName]\n  const wanted = String(fieldName).toLowerCase()\n  const actual = Object.keys(row).find((key) => key.toLowerCase() === wanted)\n  return actual === undefined ? undefined : row[actual]\n}\n\n/** Group information_schema.columns rows, tolerating column-label casing differences. */\nexport function groupColumnMetadata(rows, allowedTables = [], tableFilter = '', defaultDatabase = '') {\n  if (!Array.isArray(rows)) return { ok: false, error: '数据库驱动返回的行集合不是数组' }\n  const allowed = Array.isArray(allowedTables) ? allowedTables.map((name) => String(name).toLowerCase()) : []\n  const filter = typeof tableFilter === 'string' ? tableFilter.trim().toLowerCase() : ''\n  const database = typeof defaultDatabase === 'string' ? defaultDatabase.trim().toLowerCase() : ''\n  const byTable = new Map()\n  for (const row of rows) {\n    const tableName = readRowField(row, 'table_name')\n    const columnName = readRowField(row, 'column_name')\n    const columnType = readRowField(row, 'column_type')\n    const isNullable = readRowField(row, 'is_nullable')\n    if ([tableName, columnName, columnType, isNullable].some((value) => value === undefined || value === null)) {\n      const fields = row && typeof row === 'object' ? Object.keys(row).join(', ') : typeof row\n      return { ok: false, error: 'information_schema 返回行缺少必需字段（实际字段：' + fields + '）' }\n    }\n    const table = String(tableName).toLowerCase()\n    const tableSchema = readRowField(row, 'table_schema')\n    if (tableSchema !== undefined && tableSchema !== null && database && String(tableSchema).toLowerCase() !== database) continue\n    if (allowed.length > 0 && !allowed.includes(table)) continue\n    if (filter && !table.includes(filter)) continue\n    if (!byTable.has(table)) byTable.set(table, [])\n    const columnKey = readRowField(row, 'column_key')\n    const columnComment = readRowField(row, 'column_comment')\n    byTable.get(table).push({\n      column: String(columnName),\n      type: String(columnType),\n      nullable: String(isNullable).toUpperCase() === 'YES',\n      key: columnKey ? String(columnKey) : '',\n      comment: columnComment ? String(columnComment) : '',\n    })\n  }\n  const tables = [...byTable.keys()].sort().map((name) => ({ name, columns: byTable.get(name) }))\n  return { ok: true, tables }\n}\n\n/**\n * 去掉 SQL 注释（-- 行注释、# 行注释、\\/* *\\/ 块注释），字符串字面量保持原样，\n * 用于语句分类与多语句检测。返回与输入等长的字符串（注释替换为空格）。\n */\nexport function stripSqlComments(sql) {\n  if (typeof sql !== 'string') return ''\n  let out = ''\n  let i = 0\n  const n = sql.length\n  while (i < n) {\n    const c = sql[i]\n    const next = sql[i + 1]\n    if (c === '-' && next === '-') {\n      while (i < n && sql[i] !== '\\n') { out += ' '; i++ }\n    } else if (c === '#') {\n      while (i < n && sql[i] !== '\\n') { out += ' '; i++ }\n    } else if (c === '/' && next === '*') {\n      out += '  '\n      i += 2\n      while (i < n && !(sql[i] === '*' && sql[i + 1] === '/')) { out += ' '; i++ }\n      out += '  '\n      i += 2\n    } else if (c === \"'\" || c === '\"' || c === '`') {\n      const q = c\n      out += c\n      i++\n      while (i < n) {\n        const ch = sql[i]\n        if (ch === '\\\\' && q !== '`') {\n          out += ch\n          i++\n          if (i < n) { out += sql[i]; i++ }\n          continue\n        }\n        out += ch\n        i++\n        if (ch === q) {\n          if (sql[i] === q) { out += q; i++; continue }\n          break\n        }\n      }\n    } else {\n      out += c\n      i++\n    }\n  }\n  return out\n}\n\n/**\n * 把字符串字面量（'...' 与 \"...\"）替换为等长空格，但保留反引号标识符，\n * 供表名提取正则安全扫描（避免把字符串内容里的 FROM xxx 误判为表引用）。\n */\nexport function blankStrings(sql) {\n  if (typeof sql !== 'string') return ''\n  let out = ''\n  let i = 0\n  const n = sql.length\n  while (i < n) {\n    const c = sql[i]\n    if (c === '`') {\n      let j = i + 1\n      while (j < n) {\n        if (sql[j] === '`') {\n          if (sql[j + 1] === '`') { j += 2; continue }\n          j++\n          break\n        }\n        j++\n      }\n      out += sql.slice(i, j)\n      i = j\n      continue\n    }\n    if (c === \"'\" || c === '\"') {\n      let j = i + 1\n      while (j < n) {\n        const ch = sql[j]\n        if (ch === '\\\\') { j += 2; continue }\n        if (ch === c) {\n          if (sql[j + 1] === c) { j += 2; continue }\n          j++\n          break\n        }\n        j++\n      }\n      out += ' '.repeat(j - i)\n      i = j\n      continue\n    }\n    out += c\n    i++\n  }\n  return out\n}\n\n/**\n * 结构变更（DDL）判定：动词与对象词必须同时命中。\n *\n * 只按首词放行会把 `CREATE USER` / `DROP DATABASE` 这类账号与库级语句一起放进来 ——\n * 它们与表结构变更同为首词，但属于提权与库级操作，永久拒绝（不进 ddl 桶）。\n * 覆盖范围：CREATE/ALTER/DROP/RENAME/TRUNCATE 作用于 TABLE / VIEW / INDEX。\n */\nconst DDL_PATTERNS = [\n  /^create\\s+(?:or\\s+replace\\s+)?(?:(?:temporary|unique|fulltext|spatial)\\s+)*(?:table|view|index)\\b/i,\n  /^alter\\s+(?:(?:online|offline|ignore)\\s+)*(?:table|view)\\b/i,\n  /^drop\\s+(?:temporary\\s+)?(?:table|view|index)\\b/i,\n  /^rename\\s+tables?\\b/i,\n  /^truncate\\s+(?:table\\s+)?(?=[`A-Za-z0-9_$])/i,\n]\n\nfunction isDdlStatement(cleaned) {\n  for (const re of DDL_PATTERNS) {\n    if (re.test(cleaned)) return true\n  }\n  return false\n}\n\n/**\n * 语句分类：\n *  - read:       SELECT / SHOW / DESCRIBE / DESC / EXPLAIN\n *  - write-dml:  INSERT / UPDATE / DELETE\n *  - ddl:        CREATE / ALTER / DROP / RENAME / TRUNCATE 作用于 TABLE / VIEW / INDEX，\n *                即结构变更（要求连接显式开启 allowDdl，见 DDL_PATTERNS）\n *  - forbidden:  账号与权限类（CREATE|ALTER|DROP USER / ROLE、GRANT、REVOKE）、库级语句\n *                （CREATE|ALTER|DROP DATABASE）与 LOCK / UNLOCK / SET / USE / CALL /\n *                REPLACE / LOAD / HANDLER / DO 等 —— 与 allowDdl 无关，永久拒绝\n *  - unknown:    无法识别\n *  - empty:      空白\n */\nexport function classifyStatement(sql) {\n  const cleaned = stripSqlComments(sql).trim()\n  if (!cleaned) return 'empty'\n  if (/^select\\b/i.test(cleaned)) return 'read'\n  if (/^show\\b/i.test(cleaned)) return 'read'\n  if (/^(describe|desc)\\b/i.test(cleaned)) return 'read'\n  if (/^explain\\b/i.test(cleaned)) return 'read'\n  if (/^insert\\b/i.test(cleaned)) return 'write-dml'\n  if (/^update\\b/i.test(cleaned)) return 'write-dml'\n  if (/^delete\\b/i.test(cleaned)) return 'write-dml'\n  if (isDdlStatement(cleaned)) return 'ddl'\n  if (/^(drop|truncate|alter|create|rename|grant|revoke|lock|unlock|set|use|call|do|handler|load|replace|start|stop|kill|purge|reset|flush|analyze|optimize|repair|check)\\b/i.test(cleaned)) return 'forbidden'\n  return 'unknown'\n}\n\n/** 检测多语句：去掉注释与字符串内容后，除末尾分号外仍出现分号即视为多语句。 */\nexport function hasMultipleStatements(sql) {\n  const cleaned = blankStrings(stripSqlComments(sql)).trim()\n  const noTrailing = cleaned.replace(/;+\\s*$/, '')\n  return noTrailing.includes(';')\n}\n\n/** 提取 FROM / JOIN / UPDATE / INTO 后的表引用（小写表名；db. 前缀取最后一段）。 */\nconst TABLE_REF_RE = /\\b(from|join|update|into)\\s+((?:`[^`]+`|[A-Za-z0-9_$]+)(?:\\s*\\.\\s*(?:`[^`]+`|[A-Za-z0-9_$]+))*)/gi\n\nexport function extractTableRefs(sql) {\n  const cleaned = blankStrings(stripSqlComments(sql))\n  const names = new Set()\n  let m\n  TABLE_REF_RE.lastIndex = 0\n  while ((m = TABLE_REF_RE.exec(cleaned)) !== null) {\n    const ref = m[2].replace(/\\s+/g, '')\n    // 整体被一对反引号包裹 = 表名本身含点（如 `weird.name`），不按 db. 拆分\n    if (/^`[^`]+`$/.test(ref)) {\n      const table = ref.slice(1, -1).toLowerCase()\n      if (table) names.add(table)\n      continue\n    }\n    const parts = ref.split('.')\n    let last = parts[parts.length - 1]\n    if (last.startsWith('`') && last.endsWith('`')) last = last.slice(1, -1)\n    const table = last.toLowerCase()\n    if (table) names.add(table)\n  }\n  return [...names]\n}\n\n/**\n * 表名白名单归一化：字符串数组 → 纯小写表名（去反引号、去 db. 前缀、去重、截断）。\n * 空数组表示「不限制」。\n */\nexport function normalizeTables(tables) {\n  if (!Array.isArray(tables)) return []\n  const seen = new Set()\n  const out = []\n  for (const t of tables) {\n    const s = String(t).trim().replace(/`/g, '')\n    if (!s) continue\n    const parts = s.split('.')\n    const name = parts[parts.length - 1].toLowerCase()\n    if (!seen.has(name)) {\n      seen.add(name)\n      out.push(name)\n    }\n  }\n  return out.slice(0, 200)\n}\n\n/**\n * 校验一组表名是否全部在白名单内。\n * 白名单为空 → 放行（不限制）；否则返回 { ok:false, denied: [...] }。\n * DML（SQL 提取）与 DDL（目标对象提取）共用同一套白名单语义。\n */\nexport function checkTableRefs(names, allowlist) {\n  const list = normalizeTables(allowlist)\n  if (list.length === 0) return { ok: true }\n  const denied = []\n  for (const raw of Array.isArray(names) ? names : []) {\n    const name = String(raw).trim().replace(/`/g, '').toLowerCase()\n    if (name && !list.includes(name) && !denied.includes(name)) denied.push(name)\n  }\n  return denied.length > 0 ? { ok: false, denied } : { ok: true }\n}\n\n/**\n * 校验 SQL 引用的表是否全部在白名单内（DML 路径，沿用 FROM/JOIN/UPDATE/INTO 提取）。\n * 白名单为空 → 放行（不限制）；否则返回 { ok:false, denied: [...] }。\n */\nexport function checkTableAllowlist(sql, allowlist) {\n  return checkTableRefs(extractTableRefs(sql), allowlist)\n}\n\n// ── 结构变更（DDL）目标提取与跨库边界 ─────────────────────────────────────\n//\n// 白名单与库边界都必须看到 DDL 的目标对象，而 DDL 的语法形态与 DML 完全不同：\n// `DROP TABLE t` / `ALTER TABLE t` / `TRUNCATE t` 里没有 FROM/JOIN/UPDATE/INTO，\n// 走 extractTableRefs 会得到空集合 —— 校验会「空过」。这一节专门提取这些形态。\n\n/** 标识符：反引号包裹或裸词。 */\nconst IDENT = '(?:`[^`]+`|[A-Za-z0-9_$]+)'\n/** 可能带库名前缀的标识符：a.b / `a`.`b` / a。 */\nconst QUALIFIED = IDENT + '(?:\\\\s*\\\\.\\\\s*' + IDENT + ')*'\n\n/** 把一个（可能带库名前缀的）标识符解析为 { raw, database, name }。 */\nfunction parseRef(raw) {\n  // 去掉点号两侧的语法空格，但保留反引号标识符内部的空格。\n  const text = String(raw).trim().replace(/\\s*\\.\\s*/g, '.')\n  if (!text) return null\n  // 整体被一对反引号包裹 = 名字本身含点，不按库名拆分\n  if (/^`[^`]+`$/.test(text)) {\n    return { raw: text, database: '', name: text.slice(1, -1).toLowerCase() }\n  }\n  const parts = text.split('.')\n  const last = parts[parts.length - 1].replace(/`/g, '')\n  const dbPart = parts.length >= 2 ? parts[parts.length - 2].replace(/`/g, '') : ''\n  if (!last) return null\n  return { raw: text, database: dbPart.toLowerCase(), name: last.toLowerCase() }\n}\n\n/** 逐个取出文本里的（可能带库名前缀的）标识符。 */\nfunction collectRefs(text) {\n  const out = []\n  const re = new RegExp(QUALIFIED, 'g')\n  let m\n  while ((m = re.exec(text)) !== null) out.push(m[0])\n  return out\n}\n\n/**\n * 提取结构变更语句的目标与来源引用，返回 { created, mutated, referenced }：\n *  - created：本次创建的新对象（CREATE TABLE / VIEW，CREATE INDEX 的索引名）\n *             —— 新建的名字不可能预先出现在白名单里，因此豁免白名单校验；\n *  - mutated：被修改/删除的目标（ALTER / DROP / TRUNCATE / RENAME，以及索引语句里\n *             `ON` 之后的那张表）—— 参与白名单校验；referenced 是 CREATE ... LIKE/AS SELECT\n *             等语句中的来源表（也参与库边界与白名单检查）。\n * 每项为 { raw, database, name }；database 为空表示语句未加库名前缀。\n */\nexport function extractDdlTargets(sql) {\n  const cleaned = blankStrings(stripSqlComments(sql))\n  const created = []\n  const mutated = []\n  const referenced = []\n  const push = (bucket, raw) => {\n    const ref = parseRef(raw)\n    if (ref !== null && !bucket.some((r) => r.raw === ref.raw)) bucket.push(ref)\n  }\n  let m\n\n  const alterHead = '\\\\balter\\\\s+(?:(?:online|offline|ignore)\\\\s+)*(?:table|view)\\\\s+(?:if\\\\s+exists\\\\s+)?'\n  const alterRe = new RegExp(alterHead + '(' + QUALIFIED + ')', 'gi')\n  while ((m = alterRe.exec(cleaned)) !== null) push(mutated, m[1])\n\n  // ALTER TABLE ... RENAME [TO|AS] new_name also mutates the destination.\n  // Ignore RENAME COLUMN / RENAME INDEX, whose following identifier is not a table.\n  const alterRenameRe = new RegExp(alterHead + '(' + QUALIFIED + ')[\\\\s\\\\S]*?\\\\brename\\\\s+(?!(?:column|index)\\\\b)(?:(?:to|as)\\\\s+)?(' + QUALIFIED + ')', 'gi')\n  while ((m = alterRenameRe.exec(cleaned)) !== null) { push(mutated, m[1]); push(mutated, m[2]) }\n\n  const createRe = new RegExp('\\\\bcreate\\\\s+(?:or\\\\s+replace\\\\s+)?(?:temporary\\\\s+)?(?:table|view)\\\\s+(?:if\\\\s+not\\\\s+exists\\\\s+)?(' + QUALIFIED + ')', 'gi')\n  while ((m = createRe.exec(cleaned)) !== null) push(created, m[1])\n\n  const createIndexRe = new RegExp('\\\\bcreate\\\\s+(?:or\\\\s+replace\\\\s+)?(?:(?:unique|fulltext|spatial)\\\\s+)*index\\\\s+(' + QUALIFIED + ')\\\\s+on\\\\s+(' + QUALIFIED + ')', 'gi')\n  while ((m = createIndexRe.exec(cleaned)) !== null) { push(created, m[1]); push(mutated, m[2]) }\n\n  const dropRe = new RegExp('\\\\bdrop\\\\s+(?:temporary\\\\s+)?(?:table|view)\\\\s+(?:if\\\\s+exists\\\\s+)?(' + QUALIFIED + '(?:\\\\s*,\\\\s*' + QUALIFIED + ')*)', 'gi')\n  while ((m = dropRe.exec(cleaned)) !== null) {\n    for (const ref of collectRefs(m[1])) push(mutated, ref)\n  }\n\n  const dropIndexRe = new RegExp('\\\\bdrop\\\\s+index\\\\s+(' + QUALIFIED + ')\\\\s+on\\\\s+(' + QUALIFIED + ')', 'gi')\n  while ((m = dropIndexRe.exec(cleaned)) !== null) push(mutated, m[2])\n\n  const truncateRe = new RegExp('\\\\btruncate\\\\s+(?:table\\\\s+)?(' + QUALIFIED + ')', 'gi')\n  while ((m = truncateRe.exec(cleaned)) !== null) push(mutated, m[1])\n\n  // RENAME TABLE a TO b, c TO d —— 源名与目标名都是本次改动的对象\n  const renameRe = new RegExp('(?:\\\\brename\\\\s+tables?\\\\s+|,\\\\s*)(' + QUALIFIED + ')\\\\s+to\\\\s+(' + QUALIFIED + ')', 'gi')\n  while ((m = renameRe.exec(cleaned)) !== null) { push(mutated, m[1]); push(mutated, m[2]) }\n\n  // Also scope data/schema sources referenced by CREATE ... AS SELECT or LIKE.\n  const tableRefRe = /\\b(from|join|update|into|references)\\s+((?:`[^`]+`|[A-Za-z0-9_$]+)(?:\\s*\\.\\s*(?:`[^`]+`|[A-Za-z0-9_$]+))*)/gi\n  tableRefRe.lastIndex = 0\n  while ((m = tableRefRe.exec(cleaned)) !== null) push(referenced, m[2])\n  const likeRe = new RegExp('\\\\blike\\\\s+(' + QUALIFIED + ')', 'gi')\n  while ((m = likeRe.exec(cleaned)) !== null) push(referenced, m[1])\n\n  return { created, mutated, referenced }\n}\n\n/**\n * 跨库边界：目标对象的库名前缀必须与连接的默认库一致（未加前缀视为默认库）。\n * 默认库为空时，任何显式带库名前缀的目标都被拒绝。\n * 返回 { ok:true } 或 { ok:false, denied: [原始目标...] }。\n */\nexport function checkDatabaseBoundary(refs, defaultDatabase) {\n  const db = typeof defaultDatabase === 'string' ? defaultDatabase.trim().replace(/`/g, '').toLowerCase() : ''\n  const denied = []\n  for (const ref of Array.isArray(refs) ? refs : []) {\n    if (ref === null || typeof ref !== 'object') continue\n    const qualified = typeof ref.database === 'string' ? ref.database : ''\n    if (qualified && qualified !== db && !denied.includes(ref.raw)) denied.push(ref.raw)\n  }\n  return denied.length > 0 ? { ok: false, denied } : { ok: true }\n}\n\n/** 将 mysql2 行值转换为无损 JSON（Date/Buffer/bigint 安全）。 */\nexport function jsonSafe(value) {\n  if (value === null || value === undefined) return value\n  if (typeof value === 'bigint') return value.toString()\n  if (value instanceof Date) return value.toISOString()\n  if (typeof Buffer !== 'undefined' && Buffer.isBuffer(value)) return value.toString('base64')\n  if (Array.isArray(value)) return value.map(jsonSafe)\n  if (typeof value === 'object') {\n    const out = {}\n    for (const key of Object.keys(value)) out[key] = jsonSafe(value[key])\n    return out\n  }\n  return value\n}\n\n/**\n * 把驱动 / 服务端错误整理成一行可读文本。\n *\n * 背景：当 MySQL（或前置代理）返回 message 为空的错误包时，mysql2 的\n * `err.message` 与 `err.sqlMessage` 都会退化成空串或 `Unknown error <errno>`，\n * 而 `errno` / `code` / `sqlState` 仍然有效。此时 `String(err.message || err)`\n * 只会输出毫无信息量的「Error」/「Unknown error 1146」，把 1064、1146、1054\n * 这类关键线索丢掉。\n *\n * 规则：优先 message，缺失时退回 sqlMessage；**只有当 message 信息量为零**\n * （空串，或 mysql2 合成的 `Unknown error <errno>`）时才补上尚未出现的\n * `code` / `errno` / `sqlState`。完整可读的报错文本（ECONNREFUSED、ENOENT、\n * 真实 MySQL 错误描述）原样返回，不追加噪音。\n */\nexport function describeDbError(err) {\n  if (err === null || err === undefined) return '未知错误'\n  if (typeof err !== 'object') return String(err)\n  const message = typeof err.message === 'string' ? err.message.trim() : ''\n  const sqlMessage = typeof err.sqlMessage === 'string' ? err.sqlMessage.trim() : ''\n  const detail = message !== '' ? message : sqlMessage\n  const tags = [err.code, err.errno, err.sqlState]\n    .map((part) => (part === undefined || part === null ? '' : String(part).trim()))\n    .filter((part) => part !== '' && !detail.includes(part))\n    .join(' ')\n  const degenerate = detail === '' || /^unknown error \\d+$/i.test(detail)\n  if (!degenerate) return detail\n  if (detail !== '' && tags !== '') return detail + '（' + tags + '）'\n  if (tags !== '') return 'MySQL 错误（' + tags + '）'\n  return detail !== '' ? detail : '未知错误'\n}\n"
    },
    {
      "path": "lib/session-selection.js",
      "content": "/**\n * Session-local selected connection helpers. The map intentionally distinguishes\n * an absent session from a stored empty Set: the latter means the user explicitly\n * cleared selection and must not trigger the single-connection default again.\n */\nexport function resolveSelectedConnectionIds(connections, sessionId, selections) {\n  if (typeof sessionId !== 'string' || !sessionId) return []\n  if (!selections.has(sessionId)) {\n    const configured = Array.isArray(connections) ? connections : []\n    // A session first rendered before any connections exist is still uninitialized;\n    // adding its first connection should retain the historic auto-select behavior.\n    if (configured.length === 0) return []\n    const initial = configured.length === 1 ? [configured[0].id] : []\n    selections.set(sessionId, new Set(initial))\n  }\n  const configured = new Set((Array.isArray(connections) ? connections : []).map((connection) => connection.id))\n  const selected = selections.get(sessionId)\n  for (const id of selected) {\n    if (!configured.has(id)) selected.delete(id)\n  }\n  return [...selected]\n}\n\nexport function resolveSelectedConnection(connections, sessionId, requestedId, selections) {\n  const selectedIds = resolveSelectedConnectionIds(connections, sessionId, selections)\n  if (selectedIds.length === 0) {\n    return { error: (Array.isArray(connections) ? connections.length : 0) === 0\n      ? '尚未配置任何 MySQL 连接：请打开 设置 → MySQL 数据库 添加连接。'\n      : '当前会话尚未选择数据库连接：请在输入栏点击「数据库连接」按钮选择一个连接后再试。' }\n  }\n  let connectionId = typeof requestedId === 'string' && requestedId ? requestedId : ''\n  if (!connectionId && selectedIds.length === 1) connectionId = selectedIds[0]\n  if (!connectionId) return { error: '当前会话选择了多个数据源；请在本次 MySQL 工具调用中明确指定 connectionId。' }\n  if (!selectedIds.includes(connectionId)) return { error: '目标连接未在当前会话选中：' + connectionId + '。请先在输入栏「数据库连接」中选择该连接。' }\n  const connection = (Array.isArray(connections) ? connections : []).find((candidate) => candidate.id === connectionId)\n  if (!connection) return { error: '连接不存在：' + connectionId }\n  return { connection }\n}\n\nexport function replaceSelectedConnectionIds(connections, sessionId, ids, selections) {\n  if (typeof sessionId !== 'string' || !sessionId) return { ok: false, error: '缺少会话标识' }\n  if (!Array.isArray(ids) || ids.some((id) => typeof id !== 'string' || !id)) {\n    return { ok: false, error: '连接选择必须是有效的连接 ID 数组' }\n  }\n  const configured = new Set((Array.isArray(connections) ? connections : []).map((connection) => connection.id))\n  const next = [...new Set(ids)]\n  const missing = next.find((id) => !configured.has(id))\n  if (missing !== undefined) return { ok: false, error: '连接不存在：' + missing }\n  selections.set(sessionId, new Set(next))\n  return { ok: true, connectionIds: next }\n}\n\nexport function removeSelectedConnectionId(connectionId, selections) {\n  for (const selected of selections.values()) selected.delete(connectionId)\n}\n"
    },
    {
      "path": "lib/typert.host.js",
      "content": "/**\n * dsh-mysql Typert 清单（Host 侧）。\n * 由 @deepseek-ai/dsh-typert-loader 解析 exports[\"./typert\"] 后自动注册，\n * 并逐字段强校验（loader：dsh-typert-loader/lib/index.js validateTypertManifest）：\n *  - package 必须等于包名；\n *  - face 必须严格为 \"host\"；\n *  - codec 必须是 strict 且提供 DSH 0.2 要求的 create() factory；\n *    create() 由 dsh-api-gateway/lib/index.js 的 decode() 真正调用\n *    （codec.create().parse(value)），dsh-typert-loader 的 requireStrictCodec\n *    也要求 create 是函数，所以它必须返回带 .parse 的 zod v4 实例；\n *  - TYPERT.model 必须存在（services/events/objects 至少是空数组）——\n *    缺失会导致整个 typert-loader 行激活失败、所有插件的 RPC 路由不可用。\n * zod 因此放在 dependencies。\n */\nimport { z } from 'zod'\n\nconst args$codec = { mode: 'strict', typeSymbol: 'dsh-mysql#Args', create: () => z.record(z.string(), z.unknown()) }\nconst result$codec = { mode: 'strict', typeSymbol: 'dsh-mysql#Result', create: () => z.record(z.string(), z.unknown()) }\n\nconst invocation = (method) => ({\n  id: 'mysql/' + method,\n  service: 'mysql',\n  namespace: 'mysql',\n  method,\n  invocation: { kind: 'direct' },\n  parameters: [\n    { name: 'args', wire: 'args', source: 'json', codec: args$codec },\n  ],\n  result: result$codec,\n})\n\nconst member = (name, signature, summary, jsDoc) => ({\n  kind: 'method',\n  name,\n  signature,\n  summary,\n  jsDoc,\n})\n\nexport const TYPERT = {\n  package: 'dsh-mysql', // 必须 == package.json 的 name\n  face: 'host',         // 必须严格 \"host\"\n  schemas: [],\n  invocations: [\n    invocation('listConnections'),\n    invocation('getSelection'),\n    invocation('selectConnection'),\n    invocation('saveConnection'),\n    invocation('deleteConnection'),\n    invocation('testConnection'),\n    invocation('listTables'),\n  ],\n  model: {\n    services: [\n      {\n        description: 'dsh-mysql MySQL 连接服务 (ctx.mysql)：连接 CRUD、连通性测试、会话级选择与表列表。MySQL connection service (ctx.mysql): connection CRUD, connectivity testing, per-session selection and table listing.',\n        summary: 'dsh-mysql MySQL 连接服务 (dsh-mysql MySQL connection service)。',\n        tags: [],\n        jsDoc: '/** dsh-mysql MySQL 连接服务 (ctx.mysql)。dsh-mysql MySQL connection service (ctx.mysql). */',\n        key: 'mysql',\n        exportName: 'MysqlService',\n        members: [\n          member(\n            'listConnections',\n            'listConnections(): Promise<object>',\n            '列出全部连接的安全视图（不含密码）。List all connections without passwords.',\n            '/**\\n * 列出全部连接（安全视图：密码仅回传 hasPassword）。\\n * @returns { ok:true, connections } 或 { ok:false, error }\\n */',\n          ),\n          member(\n            'getSelection',\n            'getSelection(args: object): Promise<object>',\n            '读取会话当前选中的数据源 ID 集合与全部连接列表。Read selected source IDs and all connections for a session.',\n            '/**\\n * @param args - { sessionId }\\n * @returns { ok:true, connectionIds, connectionId (legacy scalar when exactly one selected), connections } 或 { ok:false, error }\\n */',\n          ),\n          member(\n            'selectConnection',\n            'selectConnection(args: object): Promise<object>',\n            '为当前会话原子替换已选数据源集合（会话级，支持空数组取消全部选择）。Replace a session source set.',\n            '/**\\n * @param args - { sessionId, connectionIds: string[] }；旧调用可传 connectionId 单值\\n * @returns { ok:true, connectionIds, connectionId (legacy scalar when exactly one selected), names } 或 { ok:false, error }\\n */',\n          ),\n          member(\n            'saveConnection',\n            'saveConnection(args: object): Promise<object>',\n            '新增或更新连接（编辑时密码留空 = 保留原密码）。Create or update a connection.',\n            '/**\\n * @param args - { connection: { id?, name, host, port, user, password, database, tables, allowWrite, allowDdl, ddlRiskConfirmed } }\\n * @returns { ok:true, connection } 或 { ok:false, error }\\n */',\n          ),\n          member(\n            'deleteConnection',\n            'deleteConnection(args: object): Promise<object>',\n            '删除连接并回收其连接池与会话选择。Delete a connection, its pool and selections.',\n            '/**\\n * @param args - { connectionId }\\n * @returns { ok:true } 或 { ok:false, error }\\n */',\n          ),\n          member(\n            'testConnection',\n            'testConnection(args: object): Promise<object>',\n            '测试已保存连接或未保存的表单草稿连通性。Test a saved connection or a form draft.',\n            '/**\\n * @param args - { connectionId } 或 { connection: 草稿 }\\n * @returns { ok:true, latencyMs } 或 { ok:false, error }\\n */',\n          ),\n          member(\n            'listTables',\n            'listTables(args: object): Promise<object>',\n            '读取连接可读表列表（information_schema，受白名单约束）。List readable tables for a connection.',\n            '/**\\n * @param args - { connectionId }\\n * @returns { ok:true, tables } 或 { ok:false, error }\\n */',\n          ),\n        ],\n        types: [],\n      },\n    ],\n    events: [],\n    objects: [],\n  },\n}\n\nexport default TYPERT\n"
    },
    {
      "path": "lib/client.js",
      "content": "/**\n * dsh-mysql 浏览器端 bundle（单文件，经 __ModuleLoader__ 加载）。\n *\n * 提供两个界面：\n *  - conversation.input.left：数据库连接按钮（三态）+ 连接选择面板（会话级切换）；\n *  - settings.section（id: mysql）：连接配置页（增删改、测试连接、表白名单、写权限）。\n *\n * 数据通道：\n *  - remote.mysql.*（Typert RPC，见 ./typert.host.js 与下方 CONTRIBUTION）\n *    → 连接 CRUD / 测试 / 会话选择 / 表列表；\n *  - 宿主槽位 props（sessionId）→ 会话级选择的 key。\n *\n * 红线：网关返回 {ok, value|error} 包装，host.call 里必须解包。\n * 样式全部使用 --dsw-* 主题变量，跟随全局亮/暗主题。\n */\n\nwindow.__ModuleLoader__.load({\n  id: 'dsh-mysql',\n  factory: (require) => {\n    const React = require('react')\n\n    // ── 样式注入（防重复，随插件卸载由宿主 HMR 驱动清理）─────────────────\n    const css = `\n      .dsh-mysql-root, .dsh-mysql-settings {\n        /* 强调色完全跟随官方品牌蓝；绿色仅保留给连接状态（--dm-ok） */\n        --dm-accent: var(--dsw-alias-brand-primary);\n        --dm-accent-soft: color-mix(in srgb, var(--dsw-alias-brand-primary) 14%, transparent);\n        --dm-accent-border: color-mix(in srgb, var(--dm-accent) 40%, var(--dsw-alias-border-l1));\n        --dm-ok: var(--dsw-alias-state-success-primary, #22c55e);\n        --dm-warn: var(--dsw-alias-state-warn-primary, #f59e0b);\n        --dm-danger: var(--dsw-alias-state-error-primary, #ef4444);\n        --dm-r-sm: 8px;   /* 输入框/按钮/标签 */\n        --dm-r: 12px;     /* 面板/卡片/分组 */\n        --dm-r-lg: 16px;  /* 大弹层（当前未用，保留刻度） */\n        --dm-soft-ok: color-mix(in srgb, var(--dm-ok) 12%, transparent);\n        --dm-soft-warn: color-mix(in srgb, var(--dm-warn) 12%, transparent);\n        --dm-soft-danger: color-mix(in srgb, var(--dm-danger) 12%, transparent);\n\n        /* 选择面板材质。DSH 的菜单表面是「半透明填充 + 背景模糊」成对使用的，\n           只取填充会得到一块无模糊的半透明板（文字从面板后透出）。\n           这里把两者收在一处：换回实体面板只需改 --dm-panel-fill / --dm-panel-blur 两行。 */\n        --dm-panel-fill: var(--dsw-menu-surface-fill, var(--dsw-alias-bg-layer-2, #ffffff));\n        --dm-panel-blur: var(--dsw-menu-backdrop-filter, blur(40px) saturate(150%));\n        --dm-chrome-fill: var(--dsw-alias-menu-group-header-fill, var(--dsw-alias-bg-layer-2, #ffffff));\n        --dm-field-bg: color-mix(in srgb, var(--dsw-alias-label-primary) 6%, transparent);\n        --dm-field-border: var(--dsw-alias-border-l1);\n        --dm-chips-bg: color-mix(in srgb, var(--dsw-alias-label-primary) 6%, transparent);\n        --dm-hover-bg: var(--dsw-alias-interactive-bg-hover, #2631480f);\n        --dm-active-bg: var(--dsw-alias-interactive-bg-active, var(--dsw-alias-interactive-bg-hover, #2631481a));\n        --dm-focus: var(--dsw-alias-state-business-primary, #4176e6);\n        --dm-info: var(--dsw-alias-state-business-primary, #4176e6);\n        --dm-r-panel: var(--dsw-radius-lg, 16px);\n        --dm-r-row: 10px;\n      }\n      @supports not (background: color-mix(in srgb, red 50%, blue 50%)) {\n        .dsh-mysql-root, .dsh-mysql-settings {\n          --dm-accent: var(--dsw-alias-brand-primary);\n          --dm-accent-soft: transparent;\n          --dm-accent-border: var(--dsw-alias-border-l1);\n          /* 字段与 chip 的底色不能退回 transparent —— 那正是面板「透」的来源之一 */\n          --dm-field-bg: var(--dsw-alias-bg-module-platform, var(--dsw-alias-bg-layer-2, #f5f6f7));\n          --dm-chips-bg: var(--dsw-alias-bg-module-platform, var(--dsw-alias-bg-layer-2, #f5f6f7));\n          --dm-soft-ok: transparent;\n          --dm-soft-warn: transparent;\n          --dm-soft-danger: transparent;\n        }\n        /* 无常色混合能力时，异常标签退回中性底，标识靠文字颜色 */\n        .dsh-mysql-perm.w, .dsh-mysql-perm.ddl {\n          background:var(--dsw-alias-bg-module-platform, var(--dsw-alias-bg-layer-2, #f5f6f7));\n        }\n      }\n      /* 不支持背景模糊的渲染器：退回实体面板，绝不留下无模糊的半透明板 */\n      @supports not ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {\n        .dsh-mysql-root {\n          --dm-panel-fill: var(--dsw-alias-bg-layer-2, #ffffff);\n          --dm-panel-blur: none;\n        }\n      }\n\n      /* ── 输入栏按钮 ── */\n      .dsh-mysql-root {\n        display:inline-flex; align-items:center; gap:4px; position:relative;\n        min-width:0; flex:0 1 auto;\n        border-radius:24px;\n        transition:background-color .18s ease, box-shadow .18s ease;\n      }\n      .dsh-mysql-root:hover:not(.is-disabled),\n      .dsh-mysql-root.is-expanded:not(.is-disabled) {\n        background:var(--dsw-alias-interactive-bg-hover);\n      }\n      .dsh-mysql-btn {\n        display:inline-flex; align-items:center; gap:6px;\n        height:28px; padding:0 8px; font-size:13px; line-height:1; font-family:inherit;\n        max-width:160px; min-width:112px; box-sizing:border-box;\n        color:var(--dsw-alias-label-primary);\n        border:0; border-radius:24px; cursor:pointer;\n        background:transparent;\n        transition:background-color .18s ease, color .18s ease, box-shadow .18s ease;\n      }\n      .dsh-mysql-btn-icon { flex:none; display:inline-flex; color:var(--dsw-alias-label-secondary); }\n      .dsh-mysql-btn-label {\n        flex:1 1 auto; min-width:0; overflow:hidden; text-overflow:ellipsis;\n        white-space:nowrap; text-align:left;\n      }\n      .dsh-mysql-selection-count {\n        flex:none; min-width:16px; height:16px; padding:0 4px; box-sizing:border-box;\n        display:inline-flex; align-items:center; justify-content:center; border-radius:999px;\n        background:var(--dsw-alias-interactive-bg-hover); color:var(--dsw-alias-label-secondary);\n        font-size:10px; font-weight:600; line-height:1;\n      }\n      .dsh-mysql-btn-caret {\n        flex:none; display:inline-flex; color:var(--dsw-alias-label-secondary);\n        transition:transform .15s ease;\n      }\n      .dsh-mysql-btn.is-expanded .dsh-mysql-btn-caret { transform:rotate(180deg); }\n      .dsh-mysql-btn.is-on {\n        /* 已连接：无边框 + 透明底，状态靠绿点/▾ 与图标表达 */\n        background:transparent;\n        border-color:transparent;\n        color:var(--dsw-alias-label-primary);\n        font-weight:600;\n      }\n      .dsh-mysql-btn.is-on .dsh-mysql-btn-icon,\n      .dsh-mysql-btn.is-on .dsh-mysql-btn-caret { color:var(--dm-accent, var(--dsw-alias-brand-primary)); }\n      .dsh-mysql-btn.is-off { color:var(--dsw-alias-label-secondary); font-weight:500; }\n      .dsh-mysql-btn.is-warn {\n        background:var(--dm-soft-danger);\n        border-color:transparent;\n        color:var(--dm-danger); font-weight:600;\n      }\n      .dsh-mysql-btn.is-warn .dsh-mysql-btn-icon { color:var(--dm-danger); }\n      @supports not (background: color-mix(in srgb, red 50%, blue 50%)) {\n        .dsh-mysql-btn.is-warn { background:var(--dsw-alias-bg-input, transparent); border-color:transparent; }\n      }\n      .dsh-mysql-btn .dsh-mysql-dot {\n        flex:none; width:6px; height:6px; border-radius:50%;\n        background:var(--dm-ok); box-shadow:0 0 0 3px var(--dm-soft-ok);\n      }\n      .dsh-mysql-btn:hover:not(:disabled),\n      .dsh-mysql-btn.is-expanded:not(:disabled),\n      .dsh-mysql-btn[aria-expanded=\"true\"]:not(:disabled) {\n        border-color:transparent;\n        background:var(--dsw-alias-interactive-bg-hover);\n      }\n      .dsh-mysql-btn:active:not(:disabled) { transform:none; }\n      .dsh-mysql-btn:disabled { opacity:.45; cursor:not-allowed; }\n      .dsh-mysql-btn:focus-visible {\n        outline:0;\n        box-shadow:0 0 0 2px var(--dsw-alias-border-l3, var(--dm-accent));\n      }\n\n      .dsh-mysql-spinner {\n        flex:none; width:12px; height:12px; box-sizing:border-box;\n        border:2px solid color-mix(in srgb, currentColor 35%, transparent);\n        border-top-color:currentColor; border-radius:50%;\n        animation:dm-spin .7s linear infinite;\n      }\n      @keyframes dm-spin { to { transform:rotate(360deg); } }\n\n      /* 瞬态气泡（切换/管理引导反馈）——固定右下角，不遮挡输入内容 */\n      .dsh-mysql-toast {\n        position:fixed; right:16px; bottom:16px; z-index:3000;\n        display:inline-flex; align-items:center; gap:6px;\n        padding:8px 12px; font-size:12px; line-height:16px;\n        max-width:min(320px, calc(100vw - 32px));\n        border-radius:var(--dm-r-sm); pointer-events:none;\n        background:var(--dsw-specific-menu, var(--dsw-alias-bg-layer-2));\n        border:1px solid var(--dsw-alias-border-l1);\n        box-shadow:var(--dsw-shadow-lv3, 0 8px 24px rgba(0,0,0,.18));\n        color:var(--dsw-alias-label-primary);\n        animation:dm-toast-in .2s ease-out;\n      }\n      .dsh-mysql-toast.ok { color:var(--dm-ok); }\n      .dsh-mysql-toast.err { color:var(--dm-danger); }\n      .dsh-mysql-toast.off { color:var(--dsw-alias-label-secondary); }\n      .dsh-mysql-toast-icon { flex:none; display:inline-flex; }\n      .dsh-mysql-toast-text { color:var(--dsw-alias-label-primary); white-space:normal; }\n      @keyframes dm-toast-in {\n        from { opacity:0; transform:translateX(14px); }\n        to { opacity:1; transform:translateX(0); }\n      }\n\n      /* ── 连接选择面板（官方菜单材质：填充 + 模糊 + 立体描边）── */\n      .dsh-mysql-panel {\n        position:absolute; bottom:calc(100% + 8px); right:0; z-index:150;\n        width:min(400px, calc(100vw - 32px)); box-sizing:border-box; padding:0;\n        max-height:min(520px, calc(100vh - 120px)); overflow-y:auto;\n        background:var(--dm-panel-fill);\n        -webkit-backdrop-filter:var(--dm-panel-blur);\n        backdrop-filter:var(--dm-panel-blur);\n        border:0; border-radius:var(--dm-r-panel);\n        box-shadow:var(--dsw-elevation-prominent, 0 0 0 .5px rgba(0,0,0,.16), 0 3px 8px rgba(0,0,0,.04), 0 0 20px rgba(0,0,0,.05));\n        color:var(--dsw-alias-label-primary); font-size:12px; line-height:18px; cursor:default;\n        isolation:isolate;\n        /* 滚动条对齐官方菜单：细、内缩、不压行内容 */\n        --dsh-scrollbar-width:6px;\n        --dsh-scrollbar-thumb:var(--dsw-alias-scrollbar-bg-l2, var(--dsw-alias-scrollbar-bg-l1));\n        --dsh-scrollbar-thumb-border:2px;\n        --dsh-scrollbar-track-margin:12px;\n        animation:dm-slide-in .18s ease-out;\n      }\n      @keyframes dm-slide-in {\n        from { opacity:0; transform:translateY(-8px) scale(.97); }\n        to { opacity:1; transform:translateY(0) scale(1); }\n      }\n      .dsh-mysql-panel-header {\n        display:flex; align-items:center; justify-content:space-between; gap:8px;\n        padding:11px 14px; border-bottom:1px solid var(--dsw-alias-border-l1);\n        position:sticky; top:0; z-index:1;\n        background:var(--dm-chrome-fill);\n        /* 组头色 94% 会留下 6% 的行文字残影，再叠一层模糊把滚动内容揉开 */\n        -webkit-backdrop-filter:var(--dm-panel-blur);\n        backdrop-filter:var(--dm-panel-blur);\n        border-radius:var(--dm-r-panel) var(--dm-r-panel) 0 0;\n      }\n      .dsh-mysql-panel-title { font-weight:600; font-size:13px; margin:0; }\n      .dsh-mysql-panel-sub { color:var(--dsw-alias-label-secondary); font-size:11px; margin:0; }\n      .dsh-mysql-panel-close {\n        width:22px; height:22px; padding:0; display:inline-flex; align-items:center; justify-content:center;\n        border:none; border-radius:6px; background:transparent; flex:none;\n        color:var(--dsw-alias-label-secondary); cursor:pointer;\n      }\n      .dsh-mysql-panel-close:hover { color:var(--dsw-alias-label-primary); background:var(--dm-accent-soft); }\n      .dsh-mysql-panel-close:focus-visible { outline:2px solid var(--dm-focus); outline-offset:1px; }\n\n      .dsh-mysql-search { position:relative; margin:8px 10px 2px; }\n      .dsh-mysql-search-icon {\n        position:absolute; left:8px; top:50%; transform:translateY(-50%);\n        display:inline-flex; color:var(--dsw-alias-label-secondary); pointer-events:none;\n      }\n      .dsh-mysql-search-input {\n        box-sizing:border-box; width:100%; height:32px; padding:0 30px;\n        font-size:12px; line-height:1; color:var(--dsw-alias-label-primary);\n        background:var(--dm-field-bg);\n        border:1px solid var(--dm-field-border); border-radius:var(--dm-r-sm);\n        outline:none; font-family:inherit;\n        transition:border-color .15s ease, box-shadow .15s ease;\n      }\n      .dsh-mysql-search-input:focus {\n        border-color:var